CREATE TABLE IF NOT EXISTS public.trigger_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, logged_at timestamp with time zone NOT NULL DEFAULT now(), emotion text, time_context text, impulse_intensity integer, location text, notes text, created_at timestamp with time zone NOT NULL DEFAULT now()); ALTER TABLE public.trigger_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users can view own trigger logs" ON public.trigger_logs FOR SELECT TO authenticated USING (user_id = auth.uid()); CREATE POLICY "Users can insert own trigger logs" ON public.trigger_logs FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid()); CREATE POLICY "Users can update own trigger logs" ON public.trigger_logs FOR UPDATE TO authenticated USING (user_id = auth.uid()); CREATE POLICY "Users can delete own trigger logs" ON public.trigger_logs FOR DELETE TO authenticated USING (user_id = auth.uid()); CREATE TABLE IF NOT EXISTS public.daily_checkins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, checkin_date date NOT NULL DEFAULT CURRENT_DATE, mood text, energy_level integer, notes text, created_at timestamp with time zone NOT NULL DEFAULT now(), UNIQUE(user_id, checkin_date)); ALTER TABLE public.daily_checkins ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users can view own checkins" ON public.daily_checkins FOR SELECT TO authenticated USING (user_id = auth.uid()); CREATE POLICY "Users can insert own checkins" ON public.daily_checkins FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid()); CREATE POLICY "Users can update own checkins" ON public.daily_checkins FOR UPDATE TO authenticated USING (user_id = auth.uid()); CREATE POLICY "Users can delete own checkins" ON public.daily_checkins FOR DELETE TO authenticated USING (user_id = auth.uid());